// =======================================================
// 🎯 نظام مزامنة الدروس عبر Socket.IO (مُقتصر على الإشعار/النقر)
// =======================================================

// 🔑 ID الزر المخفي: هذا هو الزر الذي سيتم النقر عليه لتشغيل Workflow تحديث الدروس.
// ID: e263b227-f83f-4564-811c-e513fa2fc24e
const BRIDGE_BUTTON_ID = "e263b227-f83f-4564-811c-e513fa2fc24e"; 
const THROTTLE_DELAY = 100;

let collectionRefreshTimeout = null;

/**
 * 💡 الدالة الجسرية (Bridge Function) - لتحديث كوليكشن الدروس
 * مهمتها: إطلاق حدث "النقر" على الزر المخفي لـ WeWeb.
 */
function triggerLessonsRefreshEvent() {
    let button = wwLib.getFrontWindow().document.querySelector(`[data-ww-uid="${BRIDGE_BUTTON_ID}"]`);
    let foundBy = 'data-ww-uid';

    if (!button) {
        // محاولة بديلة
        button = wwLib.getFrontWindow().document.querySelector(`[data-w-id="${BRIDGE_BUTTON_ID}"]`);
        foundBy = 'data-w-id (fallback)';
    }

    if (button) {
        button.click();
        console.log(`✅ Firing Lessons refresh via hidden button click (Found by ${foundBy}).`);
    } else {
        // سيظهر هذا التحذير إذا لم يكن الزر في الصفحة
        console.warn(`❌ Bridge Button Not Found: Hidden button element with ID ${BRIDGE_BUTTON_ID} not found. Lessons will not be refreshed automatically.`);
    }
}

/**
 * يضمن تنفيذ الدالة الجسرية مرة واحدة فقط في فترة قصيرة (Throttle) لتجنب التحميل الزائد.
 */
function throttleCollectionRefresh() {
    if (collectionRefreshTimeout) {
        clearTimeout(collectionRefreshTimeout);
    }
    collectionRefreshTimeout = setTimeout(() => {
        triggerLessonsRefreshEvent();
        collectionRefreshTimeout = null;
    }, THROTTLE_DELAY);
}

/**
 * دالة المعالجة الرئيسية لاستقبال أحداث Socket
 */
function handleSocketEvent(eventName) {
    console.log(`🗓 Socket event received: ${eventName}. Triggering collection refresh.`);
    throttleCollectionRefresh();
}

// ------------------------------------------------------------------
// 🔌 كتلة Socket.IO (التنفيذ الفعلي للاتصال)
// ------------------------------------------------------------------

setTimeout(() => {
    // التحقق من تحميل مكتبة Socket.IO
    if (typeof io === "undefined") { console.error("❌ Socket.IO library not loaded yet"); return; }

    const userToken = variables["0b2a1d80-743c-4e6c-bc5d-35b65e3afe84"];
    const userId = variables["10acda86-e980-4c19-8f11-c7690f01b626"];
    if (!userToken) { console.error("❌ User token not found for Socket.IO. Connection aborted."); return; }

    const socket = io("http://localhost:3000", {
        transports: ["websocket", "polling"], auth: { token: userToken }, timeout: 10000,
        reconnection: true, reconnectionAttempts: 5, reconnectionDelay: 1000,
    });

    // وضع الاتصال في النافذة ليسهل الوصول إليه إذا لزم الأمر
    wwLib.getFrontWindow().socketConnection = socket;

    socket.on("connect", () => {
        console.log("✅ Connected to Socket Server - ID:", socket.id);
        socket.emit("join_calendar", userId);
        // إطلاق تحديث أولي عند الاتصال
        triggerLessonsRefreshEvent(); 
    });

    socket.on("disconnect", (reason) => { console.log("⚠ Disconnected from server:", reason); });
    socket.on("connect_error", (error) => { console.error("❌ Connection error:", error.message); });
    socket.on("reconnect", () => {
        console.log("✅ Reconnected successfully. Rejoining rooms...");
        socket.emit("join_calendar", userId);
        triggerLessonsRefreshEvent();
    });

    // ربط أحداث الدروس بدالة المعالجة
    socket.on("calendar_event_created", () => handleSocketEvent("calendar_event_created"));
    socket.on("calendar_event_updated", () => handleSocketEvent("calendar_event_updated"));
    socket.on("calendar_event_deleted", () => handleSocketEvent("calendar_event_deleted"));
    socket.on("lesson_status_updated", () => handleSocketEvent("lesson_status_updated"));
    socket.on("lesson_updated", () => handleSocketEvent("lesson_updated"));
    
}, 1000);

// ------------------------------------------------------------------
// 🌐 جعل الدوال متاحة عالمياً (لتشغيل تحديث يدوي إذا لزم الأمر)
// ------------------------------------------------------------------

window.triggerLessonsRefreshEvent = triggerLessonsRefreshEvent; 

console.log("✅ Socket.IO Listener System Loaded (API calls removed)");

