function enableSmoothWeekTransition() {
  const doc = wwLib.getFrontDocument();
  const calendarEl = doc.querySelector('.fc-view-harness');
  if (!calendarEl) return;

  // منع التكرار لو الكود اتشغل أكتر من مرة
  if (calendarEl.dataset.smoothEnabled) return;
  calendarEl.dataset.smoothEnabled = "true";

  const runTransition = (btn, direction = 'left') => {
    if (!calendarEl) return;

    // اول حاجة نمنع الضغط السريع
    btn.disabled = true;

    // نبدأ الحركة للخارج
    calendarEl.style.transition = 'transform 0.4s ease, opacity 0.4s ease';
    calendarEl.style.opacity = '0';
    calendarEl.style.transform =
      direction === 'left' ? 'translateX(-60px)' : 'translateX(60px)';

    // بعد ما الحركة تخلص، نرجعها ونخلي الزر يشتغل تاني
    setTimeout(() => {
      btn.click(); // ← نضغط تاني علشان نغيّر الأسبوع فعليًا بعد الأنيميشن
      calendarEl.style.transition = 'none';
      calendarEl.style.opacity = '0';
      calendarEl.style.transform =
        direction === 'left' ? 'translateX(60px)' : 'translateX(-60px)';

      // بعد تبديل المحتوى، نعمل حركة دخول ناعمة
      setTimeout(() => {
        calendarEl.style.transition = 'transform 0.5s ease, opacity 0.5s ease';
        calendarEl.style.opacity = '1';
        calendarEl.style.transform = 'translateX(0)';
        btn.disabled = false;
      }, 100);
    }, 350);
  };

  const nextBtn = doc.querySelector('.fc-next-button');
  const prevBtn = doc.querySelector('.fc-prev-button');

  if (nextBtn) {
    nextBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      runTransition(nextBtn, 'left');
    });
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      runTransition(prevBtn, 'right');
    });
  }

  console.log('✅ Smooth pre-transition week animation applied correctly');
}

setTimeout(enableSmoothWeekTransition, 1500);

